    [Fact]
    public void Render_WithNullNodeStatuses_IsByteIdenticalToCurrentBehavior()
    {
        // The static `graph` command never runs live: passing nodeStatuses: null (or omitting it,
        // via the pre-existing three-argument overload) must produce the EXACT same document, since
        // the golden fixtures (examples/hello-guardrails/..., docs/plans/08-parallel-execution/
        // diagram.html) are out of this task's scope and must not need regenerating.
        string current = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
        string withNull = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, null);

        Assert.Equal(current, withNull);
        // And the static output carries neither the live-status overlay nor the auto-refresh tag.
        Assert.DoesNotContain("<meta http-equiv=\"refresh\"", withNull, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithNodeStatuses_EmitsAMetaRefreshTag()
    {
        // A non-null nodeStatuses with the default includeRefresh: true is the DURING-RUN diagram —
        // a plain file:// view must re-read itself as the run progresses, so it carries the tag.
        string live = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);
        Assert.Contains("<meta http-equiv=\"refresh\"", live, StringComparison.Ordinal);

        // ...whereas the static (no-nodeStatuses) path must NOT carry it.
        string stat = HtmlDiagramRenderer.Render(Source, Hash, OneTarget);
        Assert.DoesNotContain("<meta http-equiv=\"refresh\"", stat, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithNodeStatusesAndIncludeRefreshFalse_OmitsTheMetaRefreshTag()
    {
        // The FINAL settled render (nodeStatuses non-null — still showing each node's final settled
        // status — but includeRefresh: false, as 06-wire-diagramobserver-into-runcommand emits at
        // run-end) still draws the overlay/badges but must NOT auto-refresh.
        string final = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses, includeRefresh: false);

        Assert.DoesNotContain("<meta http-equiv=\"refresh\"", final, StringComparison.Ordinal);
        // The overlay itself is independent of includeRefresh: each status entry is still present.
        Assert.Contains(RunningId, final, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithNodeStatuses_EmitsAnOverlayForEachStatusEntry()
    {
        // Every node id in the map must appear in the overlay-rendering logic (e.g. inside the
        // embedded status-map JSON / generated JS data structure the overlay script reads) so a
        // badge can be positioned for it. A structural string-content assertion, not a browser check.
        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);

        foreach (string nodeId in SampleStatuses.Keys)
            Assert.Contains(nodeId, html, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithRunningStatus_EmitsASpinnerClass_AndSettledStatusesEmitAGlyph()
    {
        var statuses = new Dictionary<string, string>(StringComparer.Ordinal)
