            [RunningId] = "running",
            ["guardrail_01_build"] = "passed",
        };
        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, statuses);

        // A "running" node animates via a CSS @keyframes spinner (no external image/GIF dependency
        // — see the task note), distinguishable from a settled status...
        Assert.Contains("@keyframes", html, StringComparison.Ordinal);
        Assert.Contains("running", html, StringComparison.Ordinal);
        // ...which renders a static check / X / "?" glyph instead of the spinner.
        Assert.Contains("passed", html, StringComparison.Ordinal);
    }
}

